export function LandingPage({
  headline = "{{headline}}",
  ctaText = "{{ctaText}}",
  layout = "{{layout}}",
  accent = "{{accent}}",
  showFooter = {{showFooter}},
}) {
  const split = layout === "split-hero";
  return (
    <div style={{ font: "16px system-ui, sans-serif", color: "#241430", border: "1px solid #24143022",
      borderRadius: 14, overflow: "hidden", maxWidth: 480, background: "#FAF7F2" }}>
      <section style={{ color: "#FAF7F2", padding: "32px 24px", display: "flex", alignItems: "center", gap: 20,
        flexDirection: split ? "row" : "column", textAlign: split ? "left" : "center", background: accent }}>
        <div>
          <h1 style={{ margin: "0 0 14px", fontSize: 22, fontWeight: 800 }}>{headline}</h1>
          <button type="button" style={{ background: "#FAF7F2", border: "none", padding: "10px 20px", borderRadius: 8,
            fontWeight: 700, cursor: "pointer", color: accent }}>{ctaText}</button>
        </div>
        <div aria-hidden="true" style={{ flex: "1 1 120px", minHeight: 80, borderRadius: 10, background: "#FAF7F233",
          width: split ? "auto" : "100%" }} />
      </section>
      <section style={{ display: "flex", gap: 10, padding: "16px 24px" }}>
        {[0, 1, 2].map((i) => <div key={i} style={{ flex: 1, height: 34, borderRadius: 8, background: "#24143012" }} />)}
      </section>
      {showFooter && <footer style={{ padding: "12px 24px", fontSize: 12, color: "#241430aa", borderTop: "1px solid #24143018" }}>&copy; 2026 Campaign Co.</footer>}
    </div>
  );
}
